INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Comentário Bíblico Adventista VII', 'Apocalipse', 18, 0, 'ELLEN G. WHITE COMMENTS
  1 COL 79; CS 52; CT 548; CW 141; EW 245; LS 327, 375; ML 59, 63; MM 185; TM 89; 5T 383, 729; 6T 41, 406; 7T 140; 9T 40, 46
